mapper.select:
SELECT count(*) FROM job_postings jp JOIN companies c ON jp.company_id = c.company_id WHERE jp.closing_date > #{params.now}
AND c.company_name LIKE CONCAT('%', #{params.companyName}, '%')
AND jp.title LIKE CONCAT('%', #{params.title}, '%')
AND (jp.location LIKE CONCAT('%', #{params.location}, '%') OR c.location LIKE CONCAT('%', #{params.location}, '%'))
AND jp.employment_type = #{params.type}
AND ( jp.title LIKE CONCAT('%', #{params.keyword}, '%') OR jp.description LIKE CONCAT('%', #{params.keyword}, '%') OR jp.requirements LIKE CONCAT('%', #{params.keyword}, '%') OR jp.responsibilities LIKE CONCAT('%', #{params.keyword}, '%') OR c.company_name LIKE CONCAT('%', #{params.keyword}, '%') OR c.location LIKE CONCAT('%', #{params.keyword}, '%') OR c.industry LIKE CONCAT('%', #{params.keyword}, '%') )
